<div x-data="tipeKamarPage()" class="owner-page">
  <div class="owner-page-header"><div><a x-show="idKos" x-cloak :href="backUrl" @click.prevent="utils.goBack($el.href)" class="owner-back-link mb-3"><?= masterIconSvg('arrow-left','h-4 w-4') ?> Kembali</a><p class="owner-eyebrow">Pengaturan properti</p><h2 class="owner-title">Tipe, Harga &amp; Foto</h2><p class="owner-subtitle" x-text="contextKos ? 'Atur kategori kamar untuk ' + contextKos.nama_kos + '.' : 'Atur kategori kamar pada seluruh properti Anda.'"></p></div><a :href="addUrl" class="btn-primary">+ Tambah Tipe</a></div>
  <div x-show="loading" class="card p-10 text-center text-sm text-slate-500">Memuat tipe kamar...</div>
  <div x-show="!loading && !items.length" x-cloak class="owner-empty"><div class="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-primary-soft text-primary"><?= masterIconSvg('bed','h-7 w-7') ?></div><h3 class="font-semibold text-slate-900">Belum ada tipe kamar</h3><p class="mx-auto mt-1 max-w-md text-sm text-slate-500">Buat tipe agar unit kamar dapat dikelompokkan berdasarkan kapasitas dan harga.</p><a :href="addUrl" class="btn-primary mt-5">+ Tambah Tipe</a></div>
  <div x-show="!loading && items.length" x-cloak class="owner-card-grid"><template x-for="item in items" :key="item.id_tipe_kamar">
    <article class="owner-panel owner-panel-hover !p-0">
      <a :href="editUrl(item)" class="block" :aria-label="'Atur tipe ' + item.nama_tipe"><div class="property-cover"><?= masterIconSvg('bed','h-12 w-12') ?><template x-if="item.foto"><img :src="BASE_URL + '/uploads' + item.foto" :alt="'Foto ' + item.nama_tipe" class="absolute inset-0 h-full w-full object-cover" loading="lazy" @error="$event.target.style.display='none'"></template></div></a>
      <div class="property-content"><div class="owner-context-title">
        <a :href="editUrl(item)" class="min-w-0 flex-1"><p class="owner-card-muted truncate text-xs font-semibold uppercase tracking-wide" x-text="item.nama_kos"></p><h3 class="mt-1 truncate font-bold text-slate-950" x-text="item.nama_tipe"></h3></a>
        <div class="ui-actions" x-data="uiActionMenu()" @betakos:close-menus.window="closeMenu(false)" @resize.window="closeMenu()"><button type="button" x-ref="menuTrigger" class="ui-more-trigger" aria-label="Tindakan lainnya" aria-haspopup="dialog" :aria-expanded="menuOpen" @click.stop="menuOpen ? closeMenu() : showMenu()"><?= masterIconSvg('ellipsis','h-5 w-5') ?></button><template x-teleport="body"><div x-show="menuOpen" x-cloak class="ui-menu-layer" @keydown.escape.stop.prevent="closeMenu()"><div class="ui-menu-backdrop" @click="closeMenu()"></div><div x-ref="menuPanel" role="dialog" aria-modal="true" aria-label="Tindakan tipe kamar" class="ui-action-menu" :style="menuPosition" @click="if ($event.target.closest('a,button')) closeMenu(false)"><a :href="editUrl(item)"><?= masterIconSvg('pencil','h-4 w-4') ?> Ubah tipe &amp; harga</a><a :href="BASE_URL + '/pemilik/tipe-kamar/foto?id_tipe_kamar=' + item.id_tipe_kamar + '&from=kamar'"><?= masterIconSvg('image','h-4 w-4') ?> Kelola foto</a><button type="button" @click="remove(item)" class="owner-photo-action-danger"><?= masterIconSvg('trash-2','h-4 w-4') ?> Hapus tipe</button></div></div></template></div>
      </div><a :href="editUrl(item)" class="mt-3 grid grid-cols-3 divide-x divide-slate-100 rounded-xl bg-slate-50 p-3 text-center"><span><small class="block text-[11px] text-slate-500">Kapasitas</small><strong class="mt-1 block text-sm text-slate-800" x-text="item.kapasitas + ' orang'"></strong></span><span><small class="block text-[11px] text-slate-500">Harga mulai</small><strong class="mt-1 block truncate px-1 text-sm text-slate-800" x-text="item.harga_mulai ? rupiah(item.harga_mulai) : 'Belum diatur'"></strong></span><span><small class="block text-[11px] text-slate-500">Unit</small><strong class="mt-1 block text-sm text-slate-800" x-text="item.jumlah_kamar"></strong></span></a></div>
    </article>
  </template></div>
</div>
<script>
function tipeKamarPage(){return{items:[],idKos:new URLSearchParams(location.search).get('id_kos')||'',contextKos:null,loading:true,get backUrl(){return BASE_URL+(this.idKos?'/pemilik/kos/detail?id_kos='+encodeURIComponent(this.idKos):'/pemilik/kos')},get addUrl(){return BASE_URL+'/pemilik/tipe-kamar/tambah'+(this.idKos?'?id_kos='+encodeURIComponent(this.idKos):'')},editUrl(item){return BASE_URL+'/pemilik/tipe-kamar/edit?id_tipe_kamar='+item.id_tipe_kamar+'&from=kamar'},rupiah(v){return utils.formatRupiah(v)},async init(){try{const q=this.idKos?'?id_kos='+encodeURIComponent(this.idKos):'';const r=await API.get('/pemilik/tipe-kamar'+q,false);this.items=r.data||[];if(this.idKos&&this.items.length)this.contextKos={id_kos:this.items[0].id_kos,nama_kos:this.items[0].nama_kos};if(this.idKos&&!this.contextKos){const k=await API.get('/pemilik/kamar/kos',false);this.contextKos=(k.data||[]).find(x=>String(x.id_kos)===String(this.idKos))||null}}catch(e){this.items=[]}finally{this.loading=false}},async remove(item){if(Number(item.jumlah_kamar||0)>0){Alpine.store('ui').toast('Tipe masih memiliki unit kamar dan tidak dapat dihapus.','warning');return}if(!await Alpine.store('ui').confirm('Hapus tipe kamar '+item.nama_tipe+'?'))return;await API.delete('/pemilik/tipe-kamar',{id_tipe_kamar:item.id_tipe_kamar});await this.init()}}}
</script>
